//! Shopping list rules.
//!
//! Pure functions over plain data: no storage, no I/O. The wasm bindings below are what the
//! Vue app calls; the same functions can be lifted into a server later. Values cross the
//! boundary as typed objects (`Ts<T>`), with TypeScript types generated by tsify.

pub mod changes;
pub mod item_changes;
pub mod items;

use tsify::{Ts, Tsify};
use wasm_bindgen::prelude::*;

use changes::Stamp;
use item_changes::{ItemChange, ItemEdits, ItemOp, Ledger};
use items::{Item, Lists, StarterItem, Status};

/// The core's crate version, so the app can show which build it is running.
#[wasm_bindgen(js_name = coreVersion)]
pub fn core_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

/// Every item, and the conflicts waiting for the user, from the starter items and the log.
#[wasm_bindgen]
pub fn ledger(
    starter: Vec<Ts<StarterItem>>,
    changes: Vec<Ts<ItemChange>>,
) -> Result<Ts<Ledger>, JsError> {
    Ok(item_changes::ledger(&to_rust(starter)?, &unwrap_changes(changes)?).into_ts()?)
}

/// The catalogue, shopping list, cart and fill-in list.
#[wasm_bindgen]
pub fn lists(items: Vec<Ts<Item>>) -> Result<Ts<Lists>, JsError> {
    Ok(items::lists(&to_rust(items)?).into_ts()?)
}

/// Whether an item shows as chosen while picking.
#[wasm_bindgen(js_name = isOnList)]
pub fn is_on_list(item: Ts<Item>) -> Result<bool, JsError> {
    Ok(items::is_on_list(item.to_rust()?.status))
}

/// The item already called `name`, if there is one.
#[wasm_bindgen(js_name = itemNamed)]
pub fn item_named(items: Vec<Ts<Item>>, name: &str) -> Result<Option<Ts<Item>>, JsError> {
    Ok(items::item_named(&to_rust(items)?, name)
        .map(|i| i.into_ts())
        .transpose()?)
}

/// The changes that record `edits` to one item, building on every change seen so far.
#[wasm_bindgen(js_name = recordItemEdits)]
pub fn record_item_edits(
    changes: Vec<Ts<ItemChange>>,
    #[wasm_bindgen(js_name = itemId)] item_id: &str,
    edits: Vec<Ts<ItemOp>>,
    stamp: Ts<Stamp>,
) -> Result<Vec<Ts<ItemChange>>, JsError> {
    let edits = to_rust(edits)?.into_iter().map(|op| op.0).collect();
    changes::record(&unwrap_changes(changes)?, item_id, edits, &stamp.to_rust()?)
        .into_iter()
        .map(|c| Ok(ItemChange(c).into_ts()?))
        .collect()
}

#[wasm_bindgen(js_name = newItemEdits)]
pub fn new_item_edits(name: &str, aisle: &str) -> Result<Vec<Ts<ItemOp>>, JsError> {
    to_ts(item_changes::new_item_edits(name, aisle))
}

#[wasm_bindgen(js_name = pickEdit)]
pub fn pick_edit(item: Ts<Item>) -> Result<Ts<ItemOp>, JsError> {
    Ok(item_changes::pick_edit(&item.to_rust()?).into_ts()?)
}

#[wasm_bindgen(js_name = statusEdit)]
pub fn status_edit(status: Ts<Status>) -> Result<Ts<ItemOp>, JsError> {
    Ok(item_changes::status_edit(status.to_rust()?).into_ts()?)
}

#[wasm_bindgen(js_name = finishShopEdits)]
pub fn finish_shop_edits(items: Vec<Ts<Item>>) -> Result<Vec<Ts<ItemEdits>>, JsError> {
    to_ts(item_changes::finish_shop_edits(&to_rust(items)?))
}

fn to_rust<T>(values: Vec<Ts<T>>) -> Result<Vec<T>, JsError>
where
    T: Tsify + serde::de::DeserializeOwned,
    T::JsType: Clone,
{
    Ok(values
        .into_iter()
        .map(|v| v.to_rust())
        .collect::<Result<Vec<_>, _>>()?)
}

fn to_ts<T>(values: Vec<T>) -> Result<Vec<Ts<T>>, JsError>
where
    T: Tsify + serde::Serialize,
{
    values.into_iter().map(|v| Ok(v.into_ts()?)).collect()
}

fn unwrap_changes(
    changes: Vec<Ts<ItemChange>>,
) -> Result<Vec<changes::Change<item_changes::ItemEdit>>, JsError> {
    Ok(to_rust(changes)?.into_iter().map(|c| c.0).collect())
}
